import { test, expect } from '@playwright/test';
import { STATUS, openWithStatus, expectCurrentStatus } from './publish-confirmation.helpers';

test.use({ serviceWorkers: 'block' });

test('Объявление «בהמתנה» — «ממתינה לאישור», без «פורסם» и «צפה במודעה» #243006 @desktop @prod-safe', async ({ page }) => {
  const { passed } = await openWithStatus(page, STATUS.pending);

  await expect(page.getByRole('heading', { name: 'המודעה נשלחה בהצלחה וממתינה לאישור' })).toBeVisible();
  await expect(page.getByText(/המודעה תופיע באתר לאחר אישור/)).toBeVisible();
  await expect(page.getByText(/המודעות שלי/).first()).toBeVisible();

  await expect(page.getByText('העסק פורסם בהצלחה'), 'нет «העסק פורסם בהצלחה»').toHaveCount(0);
  await expect(page.getByText(/כעת פורסם/), 'нет «כעת פורסם»').toHaveCount(0);
  await expect(page.getByRole('link', { name: 'צפה במודעה' }), 'нет «צפה במודעה»').toHaveCount(0);
  await expect(page.getByRole('button', { name: 'צפה במודעה' })).toHaveCount(0);

  await expectCurrentStatus(page, STATUS.pending);
  expect(passed, 'не-GET не дошли до сервера').toEqual([]);
});
